import numpy as np
A=np.zeros((10,10),int)
for r,c in [(2,0),(2,5),(3,0),(3,3),(3,6),(3,7),(4,0),(4,3),(4,4),(4,7),(5,2),(5,6),(6,0),(6,3),(6,4),(7,4),(7,5)]: A[r,c]=1
B=np.zeros((10,10),int)
for r,c in [(2,3),(2,4),(2,8),(3,2),(3,3),(3,5),(3,8),(4,2),(4,5),(4,7),(5,5),(5,6),(6,3),(6,4),(6,6),(7,3),(7,5)]:B[r,c]=1
# Compare transforms with translations
for k in range(4):
 for flip in [False,True]:
  T=np.rot90(A,k)
  if flip:T=T[:,::-1]
  best=(999,None)
  for dr in range(-9,10):
   for dc in range(-9,10):
    U=np.zeros_like(A)
    for r,c in np.argwhere(T):
     rr,cc=r+dr,c+dc
     if 0<=rr<10 and 0<=cc<10:U[rr,cc]=1
    n=np.sum(U!=B)
    if n<best[0]:best=(n,(dr,dc))
  print(k,flip,best)
